    ((fair_pvp::CFairPvPScore*)(void*)user->GetCharacExpandData(
        (ENUM_CHARAC_EXPAND_TYPE)7))->SetGiveItem(user->get_pvp_grade() + 1);
    user->SendCmdOkPacket((ENUM_CMDPACKET)0x196);
    return 0;
