    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x19e,
                                 (unsigned char)res.m_4);
        return;
    }

    PacketGuard guard;
    guard.clear();
    guard.put_header(1, 0x19e);
    guard.put_byte(1);
    guard.put_short(res.m_8);
    guard.put_short(res.m_a);
    guard.put_short(res.m_c);

